import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react'
import type { ColDef } from 'ag-grid-community'
import { AnimatePresence, motion } from 'framer-motion'
import {
  Activity, ArrowDownRight, ArrowUpRight, Beaker, BookOpen, Boxes, BrainCircuit,
  ChartNoAxesCombined, Check, ChevronDown, CircleHelp, Clock3, Command, Database,
  Download, FlaskConical, Gauge, History, LayoutDashboard,
  Menu, Moon, MoreHorizontal, PanelLeftClose, Play, Plus, Search,
  Settings2, Sparkles, Sun, Table2, TrendingUp, Upload, WandSparkles,
  Workflow, X,
} from 'lucide-react'
import { Badge, Button, Card, SectionTitle } from './components/ui'
import DataPreparation from './components/DataPreparation'
import ModelTraining from './components/ModelTraining'
import ResultsTimeline from './components/ResultsTimeline'
import type {Candidate, CandidatePlan} from './components/ModelTraining'

const Plot = lazy(() => import('./components/Plot'))
const DataGrid = lazy(() => import('./components/DataGrid'))
const ResearchWorkbench = lazy(() => import('./components/ResearchWorkbench'))
const ResearchScheme = lazy(() => import('./components/ResearchScheme'))

import type { Dataset, Preview, ModelParameter, ModelCatalog, RunResult, ResultSeries } from './types'
type JournalEntry = { id: string; created: string; model: string; task: string; target: string; metrics: Record<string, number | null>; sizes: Record<string, number>; config: Record<string, unknown> }
type PageKey = 'overview' | 'data' | 'experiment' | 'results' | 'workflow' | 'builder' | 'models' | 'journal' | 'settings'
type DatasetReadOptions = { separator: string | null; encoding: string; decimal: string; sheet: string | number }

const navGroups = [
  { label: 'Рабочее пространство', items: [
    { id: 'overview' as PageKey, label: 'Обзор', icon: LayoutDashboard },
    { id: 'data' as PageKey, label: 'Данные', icon: Database },
    { id: 'experiment' as PageKey, label: 'Модели и подбор', icon: FlaskConical },
    { id: 'results' as PageKey, label: 'Результаты', icon: ChartNoAxesCombined },
    { id: 'workflow' as PageKey, label: 'Схема исследования', icon: Workflow },
    { id: 'builder' as PageKey, label: 'Конструктор эксперимента', icon: Workflow },
  ] },
  { label: 'Библиотека', items: [
    { id: 'models' as PageKey, label: 'Каталог моделей', icon: Boxes },
    { id: 'journal' as PageKey, label: 'Журнал запусков', icon: History },
  ] },
]
async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`/api${path}`, { ...init, headers: { 'Content-Type': 'application/json', ...init?.headers } })
  const raw = await response.text()
  let body: {detail?:unknown;message?:unknown} = {}
  try { body = raw ? JSON.parse(raw) as typeof body : {} } catch { /* non-JSON error response */ }
  if (!response.ok) {
    const detail = body.detail ?? body.message
    const fallback = raw.trim() && raw.trim() !== 'Internal Server Error' ? raw.trim() : `Ошибка API: ${response.status} · ${path}`
    throw new Error(detail == null ? fallback : String(detail))
  }
  return body as T
}

function downloadFile(filename: string, content: string, type: string) {
  const url = URL.createObjectURL(new Blob([content], { type }))
  const link = document.createElement('a')
  link.href = url; link.download = filename; link.click()
  window.setTimeout(() => URL.revokeObjectURL(url), 1000)
}

function downloadCSV(filename: string, rows: Record<string, unknown>[]) {
  if (!rows.length) return
  const headers = Object.keys(rows[0])
  const cell = (value: unknown) => `\"${String(value ?? '').replaceAll('\"', '\"\"')}\"`
  downloadFile(filename, [headers.map(cell).join(','), ...rows.map(row => headers.map(key => cell(row[key])).join(','))].join('\n'), 'text/csv;charset=utf-8')
}

function prettyMetric(value: number | null | undefined) {
  return value == null || !Number.isFinite(value) ? '—' : Math.abs(value) < 10 ? value.toFixed(3) : value.toLocaleString('ru-RU', { maximumFractionDigits: 2 })
}

function App() {
  const [page, setPage] = useState<PageKey>('overview')
  const [datasets, setDatasets] = useState<Dataset[]>([])
  const [readOptions, setReadOptions] = useState<DatasetReadOptions>({separator:null,encoding:'utf-8-sig',decimal:'.',sheet:0})
  const [selectedDataset, setSelectedDataset] = useState('')
  const [preview, setPreview] = useState<Preview | null>(null)
  const [catalog, setCatalog] = useState<ModelCatalog>({ models: [], catalog: [], schemas: {} })
  const [task, setTask] = useState('Регрессия')
  const [target, setTarget] = useState('')
  const [features, setFeatures] = useState<string[]>([])
  const [preparedFeatureNames, setPreparedFeatureNames] = useState<string[]|null>(null)
  const [model, setModel] = useState('Ridge')
  const [params, setParams] = useState<Record<string, unknown>>({})
  const [strategy, setStrategy] = useState<'manual'|'range'|'optuna'>('manual')
  const [variantCount, setVariantCount] = useState(5)
  const [candidatePlan,setCandidatePlan] = useState<CandidatePlan>(null)
  const [searchSpace, setSearchSpace] = useState<Record<string, Record<string, unknown>>>({})
  const [preparation, setPreparation] = useState<Record<string, unknown>>({calendar:true, lags:[], rolling_windows:[], rolling_stats:['mean','std'], horizon:0, drop_invalid_time:true, partial_windows:false})
  const [trainingOptions, setTrainingOptions] = useState<Record<string, unknown>>({scaler:'standard', missing_indicators:true, size_mode:'percent', test_size:0.2, validation_size:0.2, seed:42})
  const [result, setResult] = useState<RunResult | null>(() => {
    try { return JSON.parse(localStorage.getItem('mlrl-last-experiment') ?? 'null') as RunResult | null }
    catch { return null }
  })
  const [builderResult, setBuilderResult] = useState<RunResult | null>(() => {
    try { return JSON.parse(localStorage.getItem('mlrl-builder-last-experiment') ?? 'null') as RunResult | null }
    catch { return null }
  })
  const [journal, setJournal] = useState<JournalEntry[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [dark, setDark] = useState(() => localStorage.getItem('mlrl-theme') === 'dark')
  const [query, setQuery] = useState('')
  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [apiReady, setApiReady] = useState(false)
  const contentRef = useRef<HTMLDivElement>(null)
  const searchRef = useRef<HTMLInputElement>(null)

  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem('mlrl-theme', dark ? 'dark' : 'light') }, [dark])
  useEffect(() => { if(result){try{localStorage.setItem('mlrl-last-experiment',JSON.stringify(result))}catch{try{localStorage.setItem('mlrl-last-experiment',JSON.stringify({...result,series:undefined}))}catch{/* The live result remains available even when browser storage is full. */}}} }, [result])
  useEffect(() => { if(builderResult){try{localStorage.setItem('mlrl-builder-last-experiment',JSON.stringify(builderResult))}catch{try{localStorage.setItem('mlrl-builder-last-experiment',JSON.stringify({...builderResult,series:undefined}))}catch{/* Keep the live result if browser storage is full. */}}} }, [builderResult])
  useEffect(() => { contentRef.current?.scrollTo({ top: 0 }) }, [page])
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey)) return
      if (event.key.toLowerCase() === 'k') { event.preventDefault(); searchRef.current?.focus() }
      if (event.key.toLowerCase() === 'n') { event.preventDefault(); setPage('experiment') }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])
  useEffect(() => {
    api<Dataset[]>('/datasets').then(items => { setDatasets(items); setSelectedDataset(current => current || items[0]?.file || '') }).catch(err => setError(err.message))
    api('/health').then(() => setApiReady(true)).catch(() => setApiReady(false))
    api<JournalEntry[]>('/journal').then(setJournal).catch(() => undefined)
  }, [])
  useEffect(() => {
    if (!selectedDataset) { setPreview(null); return }
    let cancelled = false
    setPreview(null)
    setError('')
    api<Preview>(`/datasets/${encodeURIComponent(selectedDataset)}/preview?limit=1000`).then(data => {
      if (cancelled) return
      setPreview(data)
      setPreparedFeatureNames(null)
      const active=datasets.find(item=>item.file===selectedDataset)
      const defaultTarget=data.columns.map(c=>String(c.field)).filter(c=>!active?.timeColumns.includes(c)).at(-1)??''
      const numeric=(active?.numericColumns??[]).filter(c=>!active?.timeColumns.includes(c))
      setPreparation({feature_columns:task==='Классификация'?numeric.filter(c=>c!==defaultTarget).slice(0,1):[defaultTarget],calendar:true,lags:[],rolling_windows:[],rolling_stats:['mean','std'],horizon:0,drop_invalid_time:true,partial_windows:false,quality_flags:true,
        repair:active?.timeColumns.length?{columns:task==='Классификация'?numeric.filter(c=>c!==defaultTarget):numeric,fill_method:'linear',anomaly_method:'iqr',anomaly_action:'clip',window:48,min_history:8,threshold:3,max_gap:0,bounds:{}}:null})
      setTrainingOptions({scaler:'standard',missing_indicators:true,size_mode:'percent',test_size:.2,validation_size:.2,seed:42,split:active?.timeColumns.length?'time':'random',row_window:'last'})
      const names = data.columns.map(c => String(c.field))
      setTarget(defaultTarget)
      const timeColumns = datasets.find(item => item.file === selectedDataset)?.timeColumns ?? []
      setFeatures(names.filter(n => n !== defaultTarget && !timeColumns.includes(n)))
    }).catch(err => { if (!cancelled) setError(err.message) })
    return () => { cancelled = true }
  }, [selectedDataset])
  useEffect(() => {
    api<ModelCatalog>(`/models?task=${encodeURIComponent(task)}`).then(data => {
      setCatalog(data)
      setModel(current => data.models.includes(current) ? current : data.models[0] ?? '')
    }).catch(err => setError(err.message))
  }, [task])
  useEffect(() => {
    const schema = catalog.schemas[model] ?? {}
    setParams(Object.fromEntries(Object.entries(schema).map(([key, item]) => [key, item.default])))
  }, [catalog, model])

  useEffect(()=>{
    if(task!=='Классификация')return
    setPreparation(current=>{
      const repair=current.repair as Record<string,unknown>|null|undefined
      const columns=(repair?.columns??[]) as string[]
      const sources=(current.feature_columns??[]) as string[]
      if(!columns.includes(target)&&!sources.includes(target))return current
      return {...current,repair:repair?{...repair,columns:columns.filter(c=>c!==target)}:null,feature_columns:sources.filter(c=>c!==target)}
    })
    setFeatures(current=>current.filter(c=>c!==target))
  },[task,target])

  const activeDataset = datasets.find(item => item.file === selectedDataset)
  const filteredRows = useMemo(() => {
    if (!preview || !query.trim()) return preview?.rows ?? []
    const term = query.toLowerCase()
    return preview.rows.filter(row => Object.values(row).some(value => String(value ?? '').toLowerCase().includes(term)))
  }, [preview, query])
  const filteredCatalog = useMemo(() => catalog.catalog.filter(row => Object.values(row).join(' ').toLowerCase().includes(query.toLowerCase())), [catalog, query])
  const title = [...navGroups.flatMap(group => group.items), { id: 'settings' as PageKey, label: 'Настройки', icon: Settings2 }].find(item => item.id === page)?.label ?? 'Обзор'

  const runExperiment = async (candidates?:Candidate[]) => {
    if (!selectedDataset || !preview || !target || !features.length) return
    setLoading(true); setError('')
    try {
      const next = await api<RunResult>('/experiments', { method: 'POST', body: JSON.stringify({ dataset: selectedDataset, target, features, task, model, params: {...params,...trainingOptions}, preparation:{...preparation,target}, strategy, count:variantCount, search_space:searchSpace, candidates:candidates??[] }) })
      setResult(next); setJournal(await api<JournalEntry[]>('/journal'))
    } catch (err) { setError(err instanceof Error ? err.message : 'Не удалось обучить модель.') }
    finally { setLoading(false) }
  }
  const uploadDataset = async (file: File, navigate = true, options:DatasetReadOptions=readOptions):Promise<Dataset|undefined> => {
    setLoading(true); setError('')
    try {
      const content = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(String(reader.result).split(',')[1] ?? '')
        reader.onerror = () => reject(new Error('Не удалось прочитать файл.'))
        reader.readAsDataURL(file)
      })
      const uploaded = await api<Dataset>('/datasets/upload', { method: 'POST', body: JSON.stringify({ name: file.name, content, ...options }) })
      setDatasets(current => [uploaded, ...current.filter(item => item.file !== uploaded.file)])
      if (navigate) { setSelectedDataset(uploaded.file); setPage('data') }
      return uploaded
    } catch (err) { setError(err instanceof Error ? err.message : 'Не удалось загрузить файл.') }
    finally { setLoading(false) }
  }
  const combineDatasets = async (payload:{datasets:string[];primary:string;method:'datetime'|'rows';dayfirst:boolean|null;drop_invalid_time:boolean}) => {
    setLoading(true); setError('')
    try {
      const response=await api<{dataset:Dataset;diagnostics:string[]}>('/datasets/combine',{method:'POST',body:JSON.stringify(payload)})
      setDatasets(current=>[response.dataset,...current.filter(item=>item.file!==response.dataset.file)])
      setSelectedDataset(response.dataset.file)
      if(response.diagnostics.length)setError(response.diagnostics.join(' '))
    } catch(err) { setError(err instanceof Error?err.message:'Не удалось объединить наборы.') }
    finally { setLoading(false) }
  }
  const refreshJournal = async () => setJournal(await api<JournalEntry[]>('/journal'))



  return <div className={`app-shell ${sidebarOpen ? '' : 'sidebar-collapsed'}`}>
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Beaker size={19} /></div><div className="brand-copy"><strong>research<span>lab</span></strong><small>ML workspace</small></div><button className="icon-button sidebar-collapse" onClick={() => setSidebarOpen(false)} title="Свернуть меню"><PanelLeftClose size={17} /></button></div>
      <Button className="new-project" onClick={() => setPage('experiment')}><Plus size={16} /> Настроить модель <span className="shortcut">⌘ N</span></Button>
      <nav className="side-nav">
        {navGroups.map(group => <div className="nav-group" key={group.label}><div className="nav-heading">{group.label}</div>{group.items.map(item => {
          const Icon = item.icon
          return <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => setPage(item.id)}><Icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.id === 'results' && result && <span className="nav-dot" />}</button>
        })}</div>)}
      </nav>
      <div className="sidebar-bottom">
        <div className={`api-status ${apiReady ? 'online' : 'offline'}`}><span className="status-light" /><span>{apiReady ? 'Python API подключён' : 'Подключение к API'}</span></div>
        <button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => setPage('settings')}><Settings2 size={17} /><span>Настройки</span></button>
        <div className="profile"><div className="avatar">ML</div><div className="profile-name"><strong>Исследователь</strong><small>Локальное пространство</small></div><MoreHorizontal size={18} /></div>
      </div>
    </aside>
    <main className="main-area">
      <header className="topbar">
        {!sidebarOpen && <button className="icon-button" onClick={() => setSidebarOpen(true)} title="Открыть меню"><Menu size={18} /></button>}
        <div className="breadcrumbs"><span>Рабочее пространство</span><span className="crumb-sep">/</span><strong>{title}</strong></div>
        <div className="topbar-actions">
          <label className="global-search"><Search size={16} /><input ref={searchRef} value={query} onChange={event => setQuery(event.target.value)} placeholder="Поиск по проекту" /><kbd>⌘ K</kbd></label>
          <span className="top-divider" />
          <button className="icon-button theme-switch" onClick={() => setDark(value => !value)} title={dark ? 'Светлая тема' : 'Тёмная тема'}>{dark ? <Sun size={17} /> : <Moon size={17} />}</button>
          <button className="help-button"><CircleHelp size={17} /><span>Помощь</span></button>
          <div className="avatar avatar-small">ML</div>
        </div>
      </header>
      {error && <div className="error-banner"><X size={16} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}
      <div className="content-scroll" ref={contentRef}><AnimatePresence mode="wait">
        <motion.div key={page} initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -3 }} transition={{ duration: .16 }} className="page-content">
          {page === 'overview' && <Overview datasets={datasets} activeDataset={activeDataset} result={result} journal={journal} onGo={setPage} />}
          {page === 'data' && <DataPage datasets={datasets} selectedDataset={selectedDataset} setSelectedDataset={setSelectedDataset} preview={preview} rows={filteredRows} query={query} setQuery={setQuery} readOptions={readOptions} setReadOptions={setReadOptions} onUpload={(file,options)=>uploadDataset(file,false,options)} onCombine={combineDatasets}><DataPreparation key={selectedDataset} dataset={activeDataset} target={target} setTarget={setTarget} task={task} setTask={setTask} preparation={preparation} setPreparation={setPreparation} training={trainingOptions} setTraining={setTrainingOptions} features={features} setFeatures={setFeatures} knownFeatures={preparedFeatureNames} setKnownFeatures={setPreparedFeatureNames} onExperiment={()=>setPage('experiment')}/></DataPage>}
          {page === 'workflow' && <Suspense fallback={<div className="plot-loading">Загрузка схемы исследования…</div>}><ResearchScheme experiment={result} journal={journal} onGo={setPage} /></Suspense>}
          {page === 'builder' && <Suspense fallback={<div className="plot-loading">Загрузка конструктора…</div>}><ResearchWorkbench key="independent-workflow-builder" datasets={datasets} experiment={builderResult} journal={journal} onExperiment={setBuilderResult} onJournal={refreshJournal} onUpload={file=>uploadDataset(file,false)} /></Suspense>}
          {page === 'experiment' && <ModelTraining dataset={activeDataset} target={target} task={task} features={features} preparation={preparation} training={trainingOptions} ready={Boolean(preview)} model={model} setModel={setModel} params={params} setParams={setParams} catalog={catalog} loading={loading} onRun={runExperiment} strategy={strategy} setStrategy={setStrategy} count={variantCount} setCount={setVariantCount} space={searchSpace} setSpace={setSearchSpace} plan={candidatePlan} setPlan={setCandidatePlan} result={result} onData={()=>setPage('data')} onResults={()=>setPage('results')} />}
          {page === 'results' && <ResultsPage result={result} onGo={setPage} />}
          {page === 'models' && <ModelsPage catalog={filteredCatalog} query={query} task={task} experiment={result} />}
          {page === 'journal' && <JournalPage journal={journal} refresh={refreshJournal} />}
          {page === 'settings' && <SettingsPage dark={dark} setDark={setDark} apiReady={apiReady} />}
        </motion.div>
      </AnimatePresence></div>
      <footer className="app-footer"><span>ML Research Lab <span className="footer-version">v0.1</span></span><span><span className="footer-dot" /> Все данные обрабатываются локально</span><span>Python ML Engine</span></footer>
    </main>
  </div>
}

function Overview({ datasets, activeDataset, result, journal, onGo }: { datasets: Dataset[]; activeDataset?: Dataset; result: RunResult | null; journal: JournalEntry[]; onGo: (page: PageKey) => void }) {
  const latest = journal[0]
  const latestMetrics = result?.metrics ?? latest?.metrics
  const latestModel = result?.model ?? latest?.model
  const latestTarget = result?.target ?? latest?.target
  return <>
    <div className="page-heading"><div><div className="eyebrow"><Sparkles size={14} /> ИССЛЕДОВАТЕЛЬСКОЕ ПРОСТРАНСТВО</div><h1>Добро пожаловать в лабораторию</h1><p>Исследуйте данные, запускайте модели и сравнивайте результаты в одном месте.</p></div><Button onClick={() => onGo('experiment')}><Play size={15} fill="currentColor" /> Выбрать модель</Button></div>
    <div className="metric-grid">
      <MetricCard icon={<Database size={18} />} label="Наборы данных" value={datasets.length} foot="Доступно для исследования" color="blue" trend="Локальная библиотека" />
      <MetricCard icon={<FlaskConical size={18} />} label="Эксперименты" value={journal.length} foot="В локальном журнале" color="violet" trend={latest ? 'Последний запуск завершён' : 'Начните с первого запуска'} />
      <MetricCard icon={<BrainCircuit size={18} />} label="Последняя модель" value={latestModel ?? '—'} foot={latestTarget ? `Цель: ${latestTarget}` : 'Пока нет обученных моделей'} color="green" trend={latestModel ? 'Готова к анализу' : 'Выберите модель'} />
      <MetricCard icon={<Gauge size={18} />} label="Качество модели" value={latestMetrics ? prettyMetric(Object.values(latestMetrics)[0]) : '—'} foot={latestMetrics ? Object.keys(latestMetrics)[0] : 'Метрика появится после запуска'} color="amber" trend="Тестовая выборка" />
    </div>
    <div className="overview-grid">
      <Card className="overview-chart"><div className="card-heading"><div><h3>Обзор данных</h3><p>{activeDataset ? `${activeDataset.name} · ${activeDataset.rows.toLocaleString('ru-RU')} строк` : 'Выберите набор данных для начала'}</p></div><button className="text-action" onClick={() => onGo('data')}>Все данные <ArrowUpRight size={14} /></button></div>
        {activeDataset ? <div className="dataset-overview"><div className="dataset-big-icon"><Database size={20} /></div><div className="dataset-description"><strong>{activeDataset.name}</strong><span>{activeDataset.file}</span></div><Badge tone="green">Доступен</Badge><div className="dataset-stats"><span><b>{activeDataset.rows.toLocaleString('ru-RU')}</b> строк</span><span><b>{activeDataset.columns}</b> колонок</span></div><Button variant="secondary" onClick={() => onGo('data')}>Открыть данные <ArrowUpRight size={15} /></Button></div> : <EmptyState icon={<Database />} title="Наборы не найдены" action="Обновить страницу" />}
        <div className="chart-placeholder"><Activity size={17} /><span>Выберите набор, чтобы посмотреть динамику показателей</span><button onClick={() => onGo('data')}>Перейти к данным <ArrowUpRight size={14} /></button></div>
      </Card>
      <Card className="quick-card"><div className="card-heading"><div><h3>Быстрый старт</h3><p>Продолжите исследование</p></div><div className="spark-icon"><WandSparkles size={17} /></div></div><div className="quick-list"><QuickAction icon={<Table2 />} title="Загрузите данные" detail="Просмотрите доступные наборы" onClick={() => onGo('data')} /><QuickAction icon={<Workflow />} title="Настройте схему" detail="Подготовка → обучение → оценка" onClick={() => onGo('workflow')} /><QuickAction icon={<Play />} title="Выберите модель" detail="Настройте алгоритм и подбор" onClick={() => onGo('experiment')} /></div><div className="quick-tip"><Sparkles size={15} /><span>Для первого запуска подойдут встроенные демонстрационные данные.</span></div></Card>
    </div>
    <div className="bottom-grid"><Card className="recent-card"><div className="card-heading"><div><h3>Последний эксперимент</h3><p>Сводка результатов</p></div><button className="icon-button small-icon"><MoreHorizontal size={18} /></button></div>{latestModel && latestMetrics ? <div className="recent-result"><div className="run-avatar"><BrainCircuit size={18} /></div><div className="run-info"><strong>{latestModel}</strong><span>{latestTarget} · {result?.task ?? latest?.task}</span></div><Badge tone="green"><Check size={12} /> Завершён</Badge><div className="run-score"><strong>{prettyMetric(Object.values(latestMetrics)[0])}</strong><span>{Object.keys(latestMetrics)[0]}</span></div><button className="icon-button" onClick={() => onGo(result ? 'results' : 'journal')}><ArrowUpRight size={17} /></button></div> : <EmptyState icon={<FlaskConical />} title="Экспериментов пока нет" detail="Результаты появятся здесь после первого обучения." action="Выбрать модель" onAction={() => onGo('experiment')} />}</Card><Card className="guide-card"><div className="guide-icon"><BookOpen size={18} /></div><div><strong>Путь исследования</strong><p>От исходных данных до понятного отчёта. Каждый шаг сохраняется и воспроизводится.</p><button className="text-action" onClick={() => onGo('workflow')}>Открыть схему <ArrowUpRight size={14} /></button></div><ArrowDownRight className="guide-arrow" size={18} /></Card></div>
  </>
}

function MetricCard({ icon, label, value, foot, color, trend }: { icon: React.ReactNode; label: string; value: string | number; foot: string; color: string; trend: string }) {
  return <Card className="metric-card"><div className="metric-top"><div className={`metric-icon ${color}`}>{icon}</div><button className="icon-button tiny"><MoreHorizontal size={17} /></button></div><div className="metric-label">{label}</div><div className="metric-value">{value}</div><div className="metric-bottom"><span>{foot}</span><span className="metric-trend"><TrendingUp size={12} />{trend}</span></div></Card>
}
function QuickAction({ icon, title, detail, onClick }: { icon: React.ReactNode; title: string; detail: string; onClick: () => void }) { return <button className="quick-action" onClick={onClick}><span className="quick-action-icon">{icon}</span><span><strong>{title}</strong><small>{detail}</small></span><ArrowUpRight size={15} /></button> }
function EmptyState({ icon, title, detail, action, onAction }: { icon: React.ReactNode; title: string; detail?: string; action?: string; onAction?: () => void }) { return <div className="empty-state"><span className="empty-icon">{icon}</span><strong>{title}</strong>{detail && <p>{detail}</p>}{action && onAction && <Button variant="secondary" onClick={onAction}>{action}</Button>}</div> }

