 const [tab,setTab]=useState<'table'|'chart'|'profile'>('table');const [chartType,setChartType]=useState('line');const [xField,setXField]=useState('');const [yField,setYField]=useState('');const [sourceTitle,setSourceTitle]=useState('Исходные измерения');const [sourceXLabel,setSourceXLabel]=useState('Datetime');const [sourceYLabel,setSourceYLabel]=useState('Значение');const [sourceColor,setSourceColor]=useState('#6366f1');const [sourceLineWidth,setSourceLineWidth]=useState(1.5);const [profile,setProfile]=useState<Record<string,unknown>|null>(null)
 const [pendingFiles,setPendingFiles]=useState<File[]>([]);const [workbookSheets,setWorkbookSheets]=useState<Record<string,string[]>>({});const [selectedSheets,setSelectedSheets]=useState<Record<string,string>>({});const [uploadError,setUploadError]=useState('');const [combineSelection,setCombineSelection]=useState<string[]>([]);const [combineMethod,setCombineMethod]=useState<'datetime'|'rows'>('datetime');const [combinePrimary,setCombinePrimary]=useState(selectedDataset);const [dayfirst,setDayfirst]=useState<boolean|null>(null);const [dropInvalidTime,setDropInvalidTime]=useState(true);const [confirmRows,setConfirmRows]=useState(false)
 const inspectUploads=async(files:File[])=>{setPendingFiles(files);setUploadError('');for(const file of files.filter(item=>item.name.toLowerCase().endsWith('.xlsx'))){try{const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]??'');reader.onerror=()=>reject(new Error('Не удалось прочитать книгу.'));reader.readAsDataURL(file)});const result=await api<{sheets:string[]}>('/datasets/inspect-workbook',{method:'POST',body:JSON.stringify({name:file.name,content})});setWorkbookSheets(current=>({...current,[file.name]:result.sheets}));setSelectedSheets(current=>({...current,[file.name]:current[file.name]??result.sheets[0]??''}))}catch(error){setUploadError(error instanceof Error?error.message:'Не удалось получить листы книги.')}}}
